import java.util.Scanner;

class Cat {
    String name;
    int fish;

    Cat(String name, int fish) {
        this.name = name;
        this.fish = fish;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String who = sc.next();
        int n = sc.nextInt();

        Cat c = new Cat(who, n);
        System.out.println(c.name + " 有 " + c.fish + " 条小鱼干喵");
    }
}

