import java.util.Scanner;

class Cat {
    String name;
    int fish;

    Cat(String name, int fish) {
        this.name = name;
        this.fish = fish;
    }

    void eat(int n) {
        this.fish = this.fish + n;
    }

    void report() {
        System.out.println(this.name + " 吃了 " + this.fish + " 条喵");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String who = sc.next();
        int first = sc.nextInt();
        int more = sc.nextInt();

        Cat c = new Cat(who, first);
        c.report();
        c.eat(more);
        c.report();
    }
}

